    46  static int encode_variable_length(uint8_t *buf, int value) {
    47    int len = 0;
    48
    49    do {
    50      uint8_t byte = (uint8_t)(value % 128);
    51      value /= 128;
    52      if (value > 0) byte |= 0x80;
    53      buf[len++] = byte;
    54    } while (value > 0);
    55
    56    return len;
