    59  static uint32_t decode_variable_length(const char *buf,
    60                                         uint32_t *bytes_consumed) {
    61    const uint8_t *p = (const uint8_t *) buf;
    62    uint32_t value = 0;
    63    uint32_t multiplier = 1;
    64    uint8_t encoded_byte;
    65    uint32_t offset;
    66
    67    for (offset = 0; offset < 4; offset++) {
    68      encoded_byte = p[offset];
    69      value += (encoded_byte & 0x7F) * multiplier;
    70      multiplier *= 128;
    71
    72      if (!(encoded_byte & 0x80)) break;
    73    }
    74
    75    if (bytes_consumed != NULL) *bytes_consumed = offset + 1;
    76
    77    return value;
    78  }
