    95  static uint32_t get_properties_length(struct mg_mqtt_prop *props, int count) {
    96    uint32_t size = 0;
    97    for (int i = 0; i < count; i++) {
    98      size++;  // identifier
    99      switch (mqtt_prop_type_by_id(props[i].id)) {
