   103          break;
   104        case MQTT_PROP_TYPE_STRING:
   105          size += (uint32_t)(props[i].val.len + sizeof(uint16_t));
   106          break;
   107        case MQTT_PROP_TYPE_BINARY_DATA:
   108          size += (uint32_t)(props[i].val.len + sizeof(uint16_t));
   109          break;
   110        case MQTT_PROP_TYPE_VARIABLE_INT:
   111          size += compute_variable_length_size((uint32_t) props[i].iv);
   112          break;
   113        case MQTT_PROP_TYPE_INT:
