   199        i += 2 + prop->key.len;
   200        prop->val.len = (uint16_t)((((uint16_t) i[0]) << 8) | i[1]);
   201        prop->val.ptr = (char *) i + 2;
   202        new_pos += 2 * sizeof(uint16_t) + prop->val.len + prop->key.len;
   203        break;
   204      case MQTT_PROP_TYPE_BYTE:
