   207        break;
   208      case MQTT_PROP_TYPE_SHORT:
   209        prop->iv = (uint16_t)((((uint16_t) i[0]) << 8) | i[1]);
   210        new_pos += sizeof(uint16_t);
   211        break;
   212      case MQTT_PROP_TYPE_INT:
   213        prop->iv = ((uint32_t) i[0] << 24) | ((uint32_t) i[1] << 16) |
   214                   ((uint32_t) i[2] << 8) | i[3];
   215        new_pos += sizeof(uint32_t);
   216        break;
   217      case MQTT_PROP_TYPE_STRING:
   218        prop->val.len = (uint16_t)((((uint16_t) i[0]) << 8) | i[1]);
   219        prop->val.ptr = (char *) i + 2;
   220        new_pos += 2 + prop->val.len;
   221        break;
   222      case MQTT_PROP_TYPE_BINARY_DATA:
   223        prop->val.len = (uint16_t)((((uint16_t) i[0]) << 8) | i[1]);
